    const CookieConsent = {
        // Configuration
        cookieName: document.querySelector\('[data-site-cookie-name]'\)?.getAttribute\('data-site-cookie-name'\) || 'cookie_for_consent',
        cookieLifetime: parseInt\(document.querySelector\('[data-site-cookie-lifetime]'\)?.getAttribute\('data-site-cookie-lifetime'\) || 31536000\),
        cookieDomain: document.querySelector\('[data-site-cookie-domain]'\)?.getAttribute\('data-site-cookie-domain'\) || window.location.hostname,
